VALUES ('маълумотлар.xlsx','123','A2:G51','9a4ebfd9299d0627e327e5d9cb2589787248ea1b72486c612656d501e7381f89','workbook-v2',16,49,5,'[{"severity":"high","sourceRow":17,"issue":"Таъмирлаш ишлари учун даврийлик ва иккала маълумот тақдим этувчи бўш.","suggestedNormalization":"Қўшни сақлаш/офат қаторларига ўхшаш ойлик; Ҳудудий бошқармалар; туман корхоналар — фақат бизнес тасдиғидан кейин."},{"severity":"medium","sourceRows":"9:14","issue":"F9:F14 ва G9:G14 бирлаштирилган; физик жиҳатдан 10–14-қаторларда провайдерлар бўш кўринса ҳам, 9-қатордаги қиймат барча 6 молиявий ҳисоботга тегишли."},{"severity":"medium","sourceRows":"6:8","issue":"Маълумот тақдим этувчи-2 устунида ''-'' қўлланган; маълумот моделда null қилиб сақлаш керак."},{"severity":"medium","sourceRows":[3,4,31],"issue":"Бирламчи маълумот тақдим этувчи кўрсатилмаган."},{"severity":"medium","sourceRows":[14,15],"issue":"Қамров матни маълумот таърифи эмас (''жадвални билмадим''); ушбу каталогда тавсия этилган майдонлар билан нормаллаштирилди."},{"severity":"low","issue":"Кирилл ва лотин алифбоси, русча/инглизча атамалар аралаш: 6 ва 8-қаторларда Latin Uzbek, ''Call марказ'', 27-қаторда ''далше''."},{"severity":"low","issue":"Имло/услуб: ''Солиқ қарзлорлиги'', ''пресстурлар'', ''обектлари'', ''тўғрисдаги'', ''Ходиммаълумотлари'', ''лойиани'', ''ҳодимлар'', ''дебетор''. UIда таҳрирланган атамаларни, аудитда эса асл матнни сақлаш керак."},{"severity":"info","issue":"Файлда факт рақамлари, ўлчов бирликлари, формулалар, мисол қийматлар ёки даврлар кесимидаги маълумот йўқ; у 16 масъул тузилма ва 49 ҳисоботдан иборат талаблар каталоги."},{"severity":"info","issue":"32 ҳисобот ойлик, 16 ҳисобот доимий, 1 ҳисоботда даврийлик бўш; ҳафталик, чораклик ва йиллик даврийлик манбада йўқ."}]','validated');
