b","type":"text","required":false,"help":"Tizim uchun tavsiya etilgan qo‘shimcha maydon"},{"code":"mavjud_soni","label":"mavjud soni","type":"number","required":false,"unit":"ta","help":"Tizim uchun tavsiya etilgan qo‘shimcha maydon"},{"code":"soz_soni","label":"soz soni","type":"number","required":false,"unit":"ta","help":"Tizim uchun tavsiya etilgan qo‘shimcha maydon"},{"code":"tamirtalab_soni","label":"ta‘mirtalab soni","type":"number","required":false,"unit":"ta","help":"Tizim uchun tavsiya etilgan qo‘shimcha maydon"},{"code":"etishmaydigan_soni","label":"etishmaydigan soni","type":"number","required":false,"unit":"ta","help":"Tizim uchun tavsiya etilgan qo‘shimcha maydon"},{"code":"ornatilgan_sana","label":"o‘rnatilgan sana","type":"date","required":false,"help":"Tizim uchun tavsiya etilgan qo‘shimcha maydon"},{"code":"holat","label":"holat","type":"select","required":false,"options":["Rejalashtirilgan","Jarayonda","Yakunlangan","To‘xtatilgan"],"help":"Tizim uchun tavsiya etilgan qo‘shimcha maydon"},{"code":"foto","label":"foto","type":"file","required":false,"help":"Tizim uchun tavsiya etilgan qo‘shimcha maydon"},{"code":"koordinata","label":"koordinata","type":"geo","required":false,"help":"Tizim uchun tavsiya etilgan qo‘shimcha maydon"}]','[{"code":"ROAD_ELEMENTS_KPI_1","label":"Kuz-qish tayyorgarligi","role":"outcome","unit":"count","direction":"contextual"}]','["period","road"]',2,1,'current','workbook-v2',(SELECT id FROM app_information_catalog_imports WHERE checksum='9a4ebfd9299d0627e327e5d9cb2589787248ea1b72486c612656d501e7381f89' LIMIT 1),21,'Ҳудудий бошқармалар','туман корхоналар','Барча йўл элементларининг турлари кесимида миқдори.
